WITH DistinctLogins AS (SELECT DISTINCT id, login_date FROM Logins), RankedLogins AS (SELECT id, login_date, DATE_SUB(login_date, INTERVAL DENSE_RANK() OVER (PARTITION BY id ORDER BY login_date) DAY) AS grp FROM DistinctLogins), ActiveUserIDs AS (SELECT id FROM RankedLogins GROUP BY id, grp HAVING COUNT(*) >= 5) SELECT DISTINCT a.id, a.name FROM Accounts a JOIN ActiveUserIDs au ON a.id = au.id ORDER BY a.id;
